js-locate-item.wrong-junior:
const locate = (list, item) => {
  let index = -1;
  for (let position = 0; position < list.length; position += 1) {
    if (list[position] === item) {
      index = position;
      break;
    }
  }
  const present = index !== -1;
  return { present: present, index: index };
};

